-- Create a Delta table (schema enforced on write)
CREATE TABLE main.sales.orders (
  order_id   BIGINT,
  customer_id BIGINT,
  amount      DECIMAL(10,2),
  order_ts    TIMESTAMP
) USING DELTA;

INSERT INTO main.sales.orders VALUES
  (1, 100, 49.99, current_timestamp()),
  (2, 101, 19.50, current_timestamp());

-- Every commit is recorded in the transaction log
DESCRIBE HISTORY main.sales.orders;

-- Time travel: read the table as it was at version 0 (before the insert)
SELECT * FROM main.sales.orders VERSION AS OF 0;
SELECT * FROM main.sales.orders TIMESTAMP AS OF '2026-06-19T00:00:00';
